begin;
create schema test_cycle;create function test_cycle.ok(v boolean,m text)returns void language plpgsql set search_path=''as $$begin if v is not true then raise exception 'TEST FAILED: %',m;end if;end$$;create function test_cycle.fails(q text,m text)returns void language plpgsql set search_path=''as $$declare a text;begin begin execute q;set constraints all immediate;exception when others then a=sqlerrm;set constraints all deferred;if position(m in a)=0 then raise exception 'TEST FAILED expected %, got %',m,a;end if;return;end;raise exception 'TEST FAILED expected %',m;end$$;grant usage on schema test_cycle to authenticated;grant execute on all functions in schema test_cycle to authenticated;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('a1000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','cycle-a@test','x',now(),'{}','{}',now(),now()),('b1000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','cycle-b@test','x',now(),'{}','{}',now(),now()),('a1000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','reader@test','x',now(),'{}','{}',now(),now());
insert into public.organizations(id,legal_name)values('a1000000-0000-0000-0000-000000000010','Cycle A'),('b1000000-0000-0000-0000-000000000020','Cycle B');select private.seed_default_roles('a1000000-0000-0000-0000-000000000010','a1000000-0000-0000-0000-000000000001');select private.seed_default_roles('b1000000-0000-0000-0000-000000000020','b1000000-0000-0000-0000-000000000002');insert into public.memberships(organization_id,user_id,role_id)select 'a1000000-0000-0000-0000-000000000010','a1000000-0000-0000-0000-000000000003',id from public.roles where organization_id='a1000000-0000-0000-0000-000000000010' and name='Somente leitura';
insert into public.farms(id,organization_id,name)values('a1000000-0000-0000-0000-000000000101','a1000000-0000-0000-0000-000000000010','A1'),('a1000000-0000-0000-0000-000000000102','a1000000-0000-0000-0000-000000000010','A2'),('a1000000-0000-0000-0000-000000000103','a1000000-0000-0000-0000-000000000010','A3'),('b1000000-0000-0000-0000-000000000101','b1000000-0000-0000-0000-000000000020','B1');insert into public.crop_seasons(id,organization_id,name,season_type)values('a1000000-0000-0000-0000-000000000201','a1000000-0000-0000-0000-000000000010','2026/27','PRINCIPAL'),('b1000000-0000-0000-0000-000000000201','b1000000-0000-0000-0000-000000000020','B','PRINCIPAL');insert into public.chart_accounts(id,organization_id,code,name,managerial_type,nature,allows_allocation)values('a1000000-0000-0000-0000-000000000301','a1000000-0000-0000-0000-000000000010','A','A','OUTRO','NEUTRA',true),('b1000000-0000-0000-0000-000000000301','b1000000-0000-0000-0000-000000000020','B','B','OUTRO','NEUTRA',true);insert into public.bank_accounts(id,organization_id,bank_name,account_number)values('a1000000-0000-0000-0000-000000000401','a1000000-0000-0000-0000-000000000010','A','1'),('b1000000-0000-0000-0000-000000000401','b1000000-0000-0000-0000-000000000020','B','2');insert into public.payment_methods(id,organization_id,name)values('a1000000-0000-0000-0000-000000000501','a1000000-0000-0000-0000-000000000010','Método A'),('b1000000-0000-0000-0000-000000000501','b1000000-0000-0000-0000-000000000020','Método B');insert into public.allocation_rules(id,organization_id,crop_season_id,name,is_active)values('a1000000-0000-0000-0000-000000000601','a1000000-0000-0000-0000-000000000010','a1000000-0000-0000-0000-000000000201','45/40/15',false);insert into public.allocation_rule_items(organization_id,allocation_rule_id,farm_id,percentage)values('a1000000-0000-0000-0000-000000000010','a1000000-0000-0000-0000-000000000601','a1000000-0000-0000-0000-000000000101',45),('a1000000-0000-0000-0000-000000000010','a1000000-0000-0000-0000-000000000601','a1000000-0000-0000-0000-000000000102',40),('a1000000-0000-0000-0000-000000000010','a1000000-0000-0000-0000-000000000601','a1000000-0000-0000-0000-000000000103',15);update public.allocation_rules set is_active=true;
set local role authenticated;select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000001',true);
select test_cycle.fails($$select public.create_installment_plan('a1000000-0000-0000-0000-000000000010','Inválido',500000,'2026-01-01','SAIDA',null,'a1000000-0000-0000-0000-000000000301','a1000000-0000-0000-0000-000000000201',null,null,null,null,null,'DIRETA','a1000000-0000-0000-0000-000000000101',null,'[{"number":1,"amount":499999.99,"due_date":"2026-02-01","status":"PENDENTE"}]')$$,'INSTALLMENT_TOTAL_MUST_MATCH_PLAN');
select test_cycle.fails($$select public.create_installment_plan('a1000000-0000-0000-0000-000000000010','Duplicado',2,'2026-01-01','SAIDA',null,'a1000000-0000-0000-0000-000000000301',null,null,null,null,null,null,'DIRETA','a1000000-0000-0000-0000-000000000101',null,'[{"number":1,"amount":1,"due_date":"2026-02-01","status":"PENDENTE"},{"number":1,"amount":1,"due_date":"2026-03-01","status":"PENDENTE"}]')$$,'DUPLICATE_INSTALLMENT_NUMBER');
select public.create_installment_plan('a1000000-0000-0000-0000-000000000010','Plano 5x',500000,'2026-01-01','SAIDA',null,'a1000000-0000-0000-0000-000000000301','a1000000-0000-0000-0000-000000000201','a1000000-0000-0000-0000-000000000501','a1000000-0000-0000-0000-000000000401','DOC','Contrato',null,'RATEIO',null,'a1000000-0000-0000-0000-000000000601','[{"number":1,"amount":100000,"due_date":"2026-02-01","status":"PENDENTE"},{"number":2,"amount":100000,"due_date":"2026-03-01","status":"PENDENTE"},{"number":3,"amount":100000,"due_date":"2026-04-01","status":"PENDENTE"},{"number":4,"amount":100000,"due_date":"2026-05-01","status":"AGENDADO"},{"number":5,"amount":100000,"due_date":"2026-06-01","status":"PENDENTE"}]');
select test_cycle.ok((select count(*)=5 and sum(amount)=500000 and min(installment_number)=1 and max(installment_number)=5 from public.financial_entries where installment_plan_id is not null),'five numbered parcels total 500000');select test_cycle.ok((select sum(allocated_amount)=500000 from public.entry_allocations where financial_entry_id in(select id from public.financial_entries where installment_plan_id is not null)),'allocations equal parcels, no plan impact');select test_cycle.ok((select count(*)=15 from public.entry_allocations where allocation_rule_id='a1000000-0000-0000-0000-000000000601'),'each parcel has rateio snapshot');
select set_config('test.entry',(select id::text from public.financial_entries where installment_number=1 and installment_plan_id is not null),true);select public.set_financial_entry_schedule_status('a1000000-0000-0000-0000-000000000010',current_setting('test.entry')::uuid,'AGENDADO');select test_cycle.ok((select status='AGENDADO' from public.financial_entries where id=current_setting('test.entry')::uuid),'pending to scheduled');select public.set_financial_entry_schedule_status('a1000000-0000-0000-0000-000000000010',current_setting('test.entry')::uuid,'PENDENTE');select test_cycle.ok((select status='PENDENTE' from public.financial_entries where id=current_setting('test.entry')::uuid),'scheduled to pending');select test_cycle.fails(format('select public.set_financial_entry_schedule_status(%L,%L,%L)','a1000000-0000-0000-0000-000000000010',current_setting('test.entry'),'PAGO'),'SCHEDULE_STATUS');
select public.create_settlement('a1000000-0000-0000-0000-000000000010',current_setting('test.entry')::uuid,'a1000000-0000-0000-0000-000000000401','a1000000-0000-0000-0000-000000000501',now(),30000,'1',null);select test_cycle.ok((select settled_amount=30000 and open_amount=70000 from public.v_financial_entry_balances where financial_entry_id=current_setting('test.entry')::uuid),'partial settlement balance');select public.create_settlement('a1000000-0000-0000-0000-000000000010',current_setting('test.entry')::uuid,'a1000000-0000-0000-0000-000000000401',null,now(),20000,'2',null);select test_cycle.fails(format('select public.create_settlement(%L,%L,%L,null,now(),50000.01,null,null)','a1000000-0000-0000-0000-000000000010',current_setting('test.entry'),'a1000000-0000-0000-0000-000000000401'),'SETTLEMENTS_CANNOT_EXCEED');select set_config('test.lastsettlement',(select public.create_settlement('a1000000-0000-0000-0000-000000000010',current_setting('test.entry')::uuid,'a1000000-0000-0000-0000-000000000401',null,now(),50000,'3',null)::text),true);select test_cycle.ok((select status='PAGO' from public.financial_entries where id=current_setting('test.entry')::uuid),'multiple settlements automatically paid');update public.settlements set amount=1 where id=current_setting('test.lastsettlement')::uuid;select test_cycle.ok((select amount=50000 from public.settlements where id=current_setting('test.lastsettlement')::uuid),'settlement remains immutable through RLS');select test_cycle.fails(format('select public.reverse_settlement(%L,%L)',current_setting('test.lastsettlement'),''),'REVERSAL_REASON_REQUIRED');select public.reverse_settlement(current_setting('test.lastsettlement')::uuid,'correção','AGENDADO');select test_cycle.ok((select status='AGENDADO' from public.financial_entries where id=current_setting('test.entry')::uuid),'reversal removes paid and restores scheduled');select test_cycle.ok((select reversed_by='a1000000-0000-0000-0000-000000000001' from public.settlements where id=current_setting('test.lastsettlement')::uuid),'reversed_by protected');select test_cycle.fails(format('update public.financial_entries set amount=50000 where id=%L',current_setting('test.entry')),'FULLY_SETTLED_ENTRY_MUST_BE_PAID');
select test_cycle.fails(format('select public.create_settlement(%L,%L,%L,null,now(),1,null,null)','a1000000-0000-0000-0000-000000000010',current_setting('test.entry'),'b1000000-0000-0000-0000-000000000401'),'ACTIVE_BANK_ACCOUNT');select test_cycle.fails($$select public.create_installment_plan('a1000000-0000-0000-0000-000000000010','Cross',1,'2026-01-01','SAIDA',null,'b1000000-0000-0000-0000-000000000301',null,null,null,null,null,null,'DIRETA','a1000000-0000-0000-0000-000000000101',null,'[{"number":1,"amount":1,"due_date":"2026-02-01","status":"PENDENTE"}]')$$,'ACTIVE_CHART_ACCOUNT');select test_cycle.ok((select count(*) from public.settlements where organization_id='b1000000-0000-0000-0000-000000000020')=0,'A cannot view B settlements');
reset role;set local role authenticated;select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000003',true);select test_cycle.ok((select count(*)=5 from public.financial_entries where installment_plan_id is not null),'read only views parcels');select test_cycle.fails(format('select public.create_settlement(%L,%L,%L,null,now(),1,null,null)','a1000000-0000-0000-0000-000000000010',(select id from public.financial_entries where installment_plan_id is not null limit 1),'a1000000-0000-0000-0000-000000000401'),'PERMISSION_DENIED');select test_cycle.fails(format('select public.set_financial_entry_schedule_status(%L,%L,%L)','a1000000-0000-0000-0000-000000000010',(select id from public.financial_entries where installment_plan_id is not null limit 1),'AGENDADO'),'PERMISSION_DENIED');
